# -*- coding: utf-8 -*-
CSS = '*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#192b3c;font:14px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{background:#102c40;color:#fff;padding:18px max(5vw,18px)}header a{color:#b8f6e6}nav{display:flex;justify-content:space-between;gap:16px;max-width:940px;margin:auto}main{max-width:780px;margin:24px auto;padding:0 20px 42px}h1{font-size:clamp(26px,3.5vw,30px);line-height:1.3;letter-spacing:-.02em;margin:14px 0 10px}h2{font-size:19px;line-height:1.4;margin:26px 0 10px}h3{font-size:16px;line-height:1.45;margin:14px 0 7px}a{color:#006e65}p{margin:8px 0}small,.muted{color:#536878}.kicker{color:#087f73;font-size:13px;font-weight:700;letter-spacing:.08em}.card,section{padding:18px;background:white;border:1px solid #dbe3e9;border-radius:13px;margin:14px 0}.hint{font-size:14px;line-height:1.55;background:#e9f4f1;border-left:4px solid #168c77;padding:16px 20px;border-radius:8px}.boundary{background:#fff5dd;border:1px solid #ebd29a;padding:14px 18px;border-radius:8px;font-size:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.grid .card{margin:0}button,.button{display:inline-block;border:0;border-radius:9px;background:#087b6d;color:#fff;padding:11px 17px;font-family:inherit;font-size:15px;font-weight:600;line-height:1.5;cursor:pointer;text-decoration:none;margin:5px 6px 5px 0;min-height:48px}button.secondary,.secondary{background:#e7eef2;color:#213d50}button:disabled{opacity:.5}button:focus-visible,a:focus-visible{outline:3px solid #efb41f;outline-offset:3px}pre{background:#112d40;color:#cde9f1;padding:18px;border-radius:9px;white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.6 ui-monospace,monospace}code{overflow-wrap:anywhere}output{display:block;margin-top:16px;padding:16px;background:#eef5f8;border-radius:8px;min-height:58px;white-space:pre-wrap}.choices{display:grid;gap:8px}.choices button{text-align:left;background:#eaf0f4;color:#173447}.lesson-stops{display:flex;flex-wrap:wrap;gap:6px}.lesson-stops button{margin:0;flex:1 1 120px}.lesson-stops button[aria-pressed="true"]{background:#087b6d;color:white}#stopText{min-height:250px}.lesson-toc{position:sticky;top:8px;z-index:20;background:#fff;border:1px solid #bccfd5;border-radius:12px;padding:12px 16px;box-shadow:0 3px 14px #102c4010}.lesson-toc summary{font-weight:700}.lesson-toc nav{display:grid;gap:0;padding-top:8px}.lesson-toc a{display:block;padding:9px 0;border-top:1px solid #e5eded}.lesson-toc[open]{max-height:70vh;overflow:auto}section[id]{scroll-margin-top:88px}header nav{flex-wrap:wrap}.feedback{color:#006255;font-weight:600}progress{width:100%;height:18px;accent-color:#168c77}.status{display:inline-block;background:#dcefe9;padding:3px 10px;border-radius:30px;font-size:13px}details{margin:14px 0}summary{cursor:pointer;color:#06766c}footer{padding:25px 20px;text-align:center;font-size:13px;color:#607583}iframe{width:100%;height:650px;border:1px solid #dbe3e9;border-radius:12px}li{margin:10px 0}.step{font-size:13px;color:#61798a}.big{font-size:30px;font-weight:750}.linkrow{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}.table{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:9px;text-align:left;border-bottom:1px solid #dce4e9}textarea{width:100%;font:inherit;border:1px solid #aabcc9;padding:12px;border-radius:8px}label{display:block;margin:8px 0}.saved{font-size:13px;color:#607583}@media(max-width:600px){body{font-size:14px;line-height:1.62}main{margin-top:14px;padding:0 14px 30px}h1{font-size:24px;line-height:1.32;margin:11px 0 9px}h2{font-size:18px;margin:22px 0 9px}h3{font-size:16px;margin:12px 0 6px}.grid{grid-template-columns:1fr}section,.card{padding:14px;margin:12px 0;border-radius:11px}iframe{height:480px}button,.button{max-width:100%;font-size:13px;padding:9px 12px}nav{font-size:14px}.big{font-size:24px}}@media print{button,iframe,nav{display:none}body{background:#fff}section{break-inside:avoid}}'
COMMON = 'async function api(path,body){const r=await fetch(\'/course/api/\'+path,body?{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(body)}:{});if(!r.ok)throw Error(\'服务响应 \'+r.status);return r.json()}\nfunction quiz(id,correct,note){document.querySelectorAll(\'#\'+id+\' button\').forEach((b,i)=>b.onclick=()=>{document.querySelector(\'#\'+id+\' output\').textContent=i===correct?\'判断正确。\'+note:\'再想一下：\'+note})}\nasync function live(){const el=document.getElementById(\'live\');if(!el)return;try{const d=await api(\'live\');el.textContent=\'课程服务在线 · 已运行 \'+Math.floor(d.uptime_seconds/60)+\' 分钟；原工作台\'+(d.workbench_reachable?\'可达\':\'暂不可达\')+\'。刷新时间 \'+new Date(d.checked_at*1000).toLocaleTimeString();}catch(e){el.textContent=\'暂时无法读取服务状态，请点击重试。\'}}\nfunction wireNotes(){document.querySelectorAll(\'textarea[data-note]\').forEach(e=>{try{e.value=localStorage.getItem(\'hami-note-\'+e.dataset.note)||\'\'}catch{}e.oninput=()=>{try{localStorage.setItem(\'hami-note-\'+e.dataset.note,e.value)}catch{}}})}wireNotes();live();document.querySelectorAll(\'.lesson-toc a[href^="#"]\').forEach(a=>a.addEventListener(\'click\',()=>a.closest(\'details\').open=false));'
js2 = "quiz('q2',1,'每卡只剩 3 GiB，单卡需要 4 GiB；两份 3 GiB 不能在这个请求模型下相加。');for(const name of ['fragmented','packed','shared'])document.getElementById(name).onclick=async()=>{const out=document.getElementById('scheduleResult');out.textContent='正在向课程服务器请求…';try{const d=await api('schedule',{case:name});out.textContent='服务器返回：'+d.state+'\\n总余量：'+d.total_free_mib/1024+' GiB；每卡余量：'+d.used_mib.map(x=>(8192-x)/1024+' GiB').join(' / ')+'\\n'+(d.selected_minor===null?'没有任何一张卡放得下。':'选择 GPU-'+d.selected_minor+'，预算可放下。');const raw=document.getElementById('scheduleRaw');raw.hidden=false;raw.textContent=JSON.stringify(d,null,2)}catch(e){out.textContent=e.message}};"
js3 = "let used=0,pending=false;function redraw(){document.getElementById('used').textContent=used/1024+' GiB';document.getElementById('memorybar').value=used}document.querySelectorAll('[data-alloc]').forEach(b=>b.onclick=async()=>{if(pending)return;pending=true;try{const d=await api('memory',{used_mib:used,request_mib:Number(b.dataset.alloc)});used=d.after_mib;redraw();document.getElementById('memoryResult').textContent=(d.accepted?'允许：预算内，模型继续执行。':'拒绝：超过剩余预算，模型不转交 Driver。')+'\\n已用预算 '+used/1024+' GiB。'+(d.accepted?'模拟假定底层申请成功。':'拒绝后占用不增加。')}catch(e){document.getElementById('memoryResult').textContent=e.message}finally{pending=false}});document.getElementById('reset').onclick=()=>{if(pending)return;used=0;redraw();document.getElementById('memoryResult').textContent='本页预算已重置。'};quiz('q3',1,'运行时要看实际调用和限制效果；注解或节点容量只说明配置与登记。');"
